[
  {
    "find": "Callers of `getResolvedAddress` (RM web app URLs, web proxy and AM filter URI bases, the timeline collector address) now get a valid `[IPv6]:port`, matching the format `SecurityUtil.buildTokenService` already uses.",
    "replace": "Callers of `getResolvedAddress` now get a valid `[IPv6]:port`, matching the format that `SecurityUtil.buildTokenService` already uses. Those callers are the RM web app URLs, the URI bases for the web proxy and AM filter, and the timeline collector address.",
