  },
  {
    "find": "No other argv changes.",
    "replace": "No other argv changes are made.",
    "type": "telegraphic",
    "reason": "The original is a fragment with the verb dropped."
  },
  {
    "find": "New tests cover byte-based classification, rejecting changed or unsupported files, the `--add-dir` placement, the manifest, and a fake-CLI run that checks the grant and the manifest end to end.",
    "replace": "The new tests cover classification by file bytes and rejection of changed or unsupported files. They also cover placement of `--add-dir`, the manifest, and a fake-CLI run that checks the grant and the manifest end to end.",
