  {
    "find": "correctly (`WN_CLAUDE_LIVE_IMAGE` / `WN_CLAUDE_LIVE_EXPECT`).",
    "replace": "correctly, using `WN_CLAUDE_LIVE_IMAGE` and `WN_CLAUDE_LIVE_EXPECT`.",
    "type": "telegraphic",
    "reason": "The slash stands in for a missing connective, and the relation of the env vars to the check is left implicit."
  },
  {
    "find": "Some existing subprocess timing tests in this crate occasionally fail",
    "replace": "Some existing tests of subprocess timing in this crate occasionally fail",
    "type": "noun-stack",
    "reason": "'subprocess timing tests' stacks three nouns as modifiers; 'tests of subprocess timing' is easier to parse."
  }
]

[
