  {
    "find": "Build clean with warnings as errors; `dotnet format --verify-no-changes` passes",
    "replace": "The build is clean with warnings as errors, and `dotnet format --verify-no-changes` passes.",
    "type": "telegraphic",
    "reason": "The bullet drops the subject and verb, and the semicolon joins two statements too tersely."
